dashboard.definition:
{
  "title": "Wazuh - Case management - Dashboard",
  "description": "Case management - Dashboard of the Wazuh dashboard, on the findings exported from the Wazuh indexer.",
  "inputs": {
    "input_global_trp": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "global_time",
        "defaultValue": "-24h@h,now"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "dataSources": {
    "ds_01": {
      "type": "ds.search",
      "name": "Cases by status",
      "options": {
        "query": "`wazuh_findings` \"wazuh.case.status\"=* | eval f1='wazuh.case.status' | stats count as metric by f1 | sort - metric | head 10 | rename f1 as \"Status\", metric as \"Status count\""
      }
    },
    "ds_02": {
      "type": "ds.search",
      "name": "Findings over time",
      "options": {
        "query": "`wazuh_findings` \"wazuh.case.status\"=* | timechart count as \"Count\""
      }
    },
    "ds_03": {
      "type": "ds.search",
      "name": "Cases over time by severity",
      "options": {
        "query": "`wazuh_findings` \"wazuh.case.status\"=* | eval f1='wazuh.case.severity' | timechart span=1d useother=f usenull=f limit=10 count by f1"
      }
    },
    "ds_04": {
      "type": "ds.search",
      "name": "Top case creator by status",
      "options": {
        "query": "`wazuh_findings` \"wazuh.case.status\"=* | eval f1='wazuh.case.user.name', f2='wazuh.case.status' | chart count over f1 by f2 useother=f usenull=f limit=10 | addtotals fieldname=total | sort - total | head 5 | fields - total | rename f1 as \"User\""
      }
    },
    "ds_05": {
      "type": "ds.search",
      "name": "Cases by severity",
      "options": {
        "query": "`wazuh_findings` \"wazuh.case.status\"=* | eval f1='wazuh.case.severity' | stats count as metric by f1 | sort - metric | head 10 | rename f1 as \"Severity\", metric as \"Count\""
      }
    },
    "ds_06": {
      "type": "ds.search",
      "name": "Cases by priority",
      "options": {
        "query": "`wazuh_findings` \"wazuh.case.status\"=* | eval f1='wazuh.case.priority' | stats count as metric by f1 | sort - metric | head 10 | rename f1 as \"Priority\", metric as \"Count\""
      }
    },
    "ds_07": {
      "type": "ds.search",
      "name": "Cases by TLP",
      "options": {
        "query": "`wazuh_findings` \"wazuh.case.status\"=* | eval f1='wazuh.case.tlp' | stats count as metric by f1 | sort - metric | head 10 | rename f1 as \"TLP\", metric as \"Count\""
      }
    }
  },
  "visualizations": {
    "viz_01": {
      "type": "splunk.bar",
      "title": "Cases by status",
      "dataSources": {
        "primary": "ds_01"
      },
      "options": {}
    },
    "viz_02": {
      "type": "splunk.line",
      "title": "Findings over time",
      "dataSources": {
        "primary": "ds_02"
      },
      "options": {}
    },
    "viz_03": {
      "type": "splunk.area",
      "title": "Cases over time by severity",
      "dataSources": {
        "primary": "ds_03"
      },
      "options": {
        "stackMode": "stacked"
      }
    },
    "viz_04": {
      "type": "splunk.bar",
      "title": "Top case creator by status",
      "dataSources": {
        "primary": "ds_04"
      },
      "options": {
        "stackMode": "stacked"
      }
    },
    "viz_05": {
      "type": "splunk.pie",
      "title": "Cases by severity",
      "dataSources": {
        "primary": "ds_05"
      },
      "options": {
        "showDonutHole": true
      }
    },
    "viz_06": {
      "type": "splunk.pie",
      "title": "Cases by priority",
      "dataSources": {
        "primary": "ds_06"
      },
      "options": {
        "showDonutHole": true
      }
    },
    "viz_07": {
      "type": "splunk.pie",
      "title": "Cases by TLP",
      "dataSources": {
        "primary": "ds_07"
      },
      "options": {
        "showDonutHole": true
      }
    }
  },
  "layout": {
    "type": "absolute",
    "options": {
      "width": 1200,
      "height": 616,
      "display": "auto-scale"
    },
    "globalInputs": [
      "input_global_trp"
    ],
    "structure": [
      {
        "item": "viz_01",
        "type": "block",
        "position": {
          "x": 0,
          "y": 0,
          "w": 596,
          "h": 176
        }
      },
      {
        "item": "viz_02",
        "type": "block",
        "position": {
          "x": 600,
          "y": 0,
          "w": 596,
          "h": 176
        }
      },
      {
        "item": "viz_03",
        "type": "block",
        "position": {
          "x": 0,
          "y": 180,
          "w": 596,
          "h": 236
        }
      },
      {
        "item": "viz_04",
        "type": "block",
        "position": {
          "x": 600,
          "y": 180,
          "w": 596,
          "h": 236
        }
      },
      {
        "item": "viz_05",
        "type": "block",
        "position": {
          "x": 0,
          "y": 420,
          "w": 396,
          "h": 176
        }
      },
      {
        "item": "viz_06",
        "type": "block",
        "position": {
          "x": 400,
          "y": 420,
          "w": 396,
          "h": 176
        }
      },
      {
        "item": "viz_07",
        "type": "block",
        "position": {
          "x": 800,
          "y": 420,
          "w": 396,
          "h": 176
        }
      }
    ]
  }
}
